import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_join_TriageGen2Test {









    @Test
    public void testJoin_WithNullElements() {
        // if (array[i] != null) buf.append(array[i]);
        // If element is null, it should be skipped but the separator logic still triggers
        Object[] array = {"A", null, "C", null, "E"};
        // i=0: "A"
        // i=1: append ',', array[1] is null, nothing appended
        // i=2: append ',', "C"
        // i=3: append ',', array[3] is null, nothing appended
        // i=4: append ',', "E"
        assertEquals("A,,C,,E", StringUtils.join(array, ',', 0, 5));

        // Test null at start
        Object[] array2 = {null, "B", "C"};
        assertEquals("B,C", StringUtils.join(array2, ',', 0, 3));

        // Test null at end
        Object[] array3 = {"A", "B", null};
        assertEquals("A,B", StringUtils.join(array3, ',', 0, 3));
    }




}

